legacy-sync-consumer:
  product-cdc:
    enabled: ${KAFKA_CDC_PRODUCT_ENABLED:false}
    bootstrap-servers: ${KAFKA_LEGACY_SYNC_PRODUCT_SERVER}
    topic: ${KAFKA_LEGACY_SYNC_PRODUCT_TOPIC}
    group-id: ${KAFKA_LEGACY_SYNC_PRODUCT_GROUP_ID}
    concurrency: ${KAFKA_LEGACY_SYNC_PRODUCT_CONCURRENCY}
    properties:
      auto-offset-reset: ${KAFKA_LEGACY_SYNC_PRODUCT_PROP_AUTO_OFFSET_RESET}
      enable-auto-commit: ${KAFKA_LEGACY_SYNC_PRODUCT_PROP_ENABLE_AUTO_COMMIT}
      max-poll-records: ${KAFKA_LEGACY_SYNC_PRODUCT_PROP_MAX_POLL_RECORDS}
      fetch-max-wait-ms: ${KAFKA_LEGACY_SYNC_PRODUCT_PROP_FETCH_MAX_WAIT_MS}
      fetch-min-size: ${KAFKA_LEGACY_SYNC_PRODUCT_PROP_FETCH_MIN_SIZE}
      session-timeout-ms: ${KAFKA_LEGACY_SYNC_PRODUCT_PROP_SESSION_TIMEOUT_MS}
      schema-registry-url: ${KAFKA_LEGACY_SYNC_PRODUCT_PROP_SCHEMA_REGISTRY_URL}
      specific-avro-reader: ${KAFKA_LEGACY_SYNC_PRODUCT_PROP_SPECIFIC_AVRO_READER}
      heartbeat-interval-ms: ${KAFKA_LEGACY_SYNC_PRODUCT_PROP_HEARTBEAT_INTERVAL_MS}
      security-protocol: ${KAFKA_LEGACY_SYNC_PRODUCT_PROP_SECURITY_PROTOCOL}
      sasl-mechanism: ${KAFKA_LEGACY_SYNC_PRODUCT_PROP_SASL_MECHANISM}
      sasl-jaas-config: ${KAFKA_LEGACY_SYNC_PRODUCT_PROP_SASL_JAAS_CONFIG}

client:
  legacy-api:
    baseUrl: ${LEGACY_API_BASEURL}
    timeout: ${LEGACY_API_TIMEOUT:500}
  proxy-api:
    baseUrl: ${PROXY_API_BASEURL}
    username: ${PROXY_API_USERNAME}
    password: ${PROXY_API_PASSWORD}

valkey:
  backend:
    hosts: ${VALKEY_BACKEND_HOST}
    password: ${VALKEY_BACKEND_PASSWORD}
    database: ${VALKEY_BACKEND_DATABASE}
